			store.commit();
			assertMetadataProof(store, new ArrayList<>(List.of(absent, 900L)), new ArrayList<>(), 4,
					List.of(absent));
			store.startTransaction();
			for (int i = 1; i <= 10_000; i++) {
				store.storeTriple(102 + 128L * i, 2, 900, 0, true);
			}
			store.commit();
			assertMetadataProof(store, new ArrayList<>(List.of(absent, 900L)), new ArrayList<>(), 4,
					List.of(absent));
